#include <stdio.h>
#include <stdlib.h>
int cmp(const void *a, const void *b) {
    long long diff = *(long long*)a - *(long long*)b;
    return (diff > 0) - (diff < 0);
}
int main() {
    int n; if (scanf("%d", &n) != 1) return 0;
    long long a[200005];
    for (int i = 0; i < 2 * n; i++) scanf("%lld", &a[i]);
    qsort(a, 2 * n, sizeof(long long), cmp);
    long long sum = a[n - 1] + a[n];
    if (sum % 2 == 0) printf("%lld\n", sum / 2);
    else printf("%.1f\n", (double)sum / 2.0);
    return 0;
}

