using namespace std;
int main() {
    int n; if (!(cin >> n)) return 0;
    vector<long long> a(2 * n);
    for (int i = 0; i < 2 * n; i++) cin >> a[i];
    sort(a.begin(), a.end());
    long long sum = a[n - 1] + a[n];
    if (sum % 2 == 0) cout << (sum / 2) << "\n";
    else cout << ((double)sum / 2.0) << "\n";
    return 0;
}

