import java.util.Scanner;
import java.util.Arrays;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextInt()) {
            int n = sc.nextInt();
            long[] a = new long[2 * n];
            for (int i = 0; i < 2 * n; i++) a[i] = sc.nextLong();
            Arrays.sort(a);
            long sum = a[n - 1] + a[n];
            if (sum % 2 == 0) System.out.println(sum / 2);
            else System.out.println((double)sum / 2.0);
        }
    }
}

