const fs = require("fs");
function main() {
    const toks = fs.readFileSync(0, "utf-8").trim().split(/\s+/);
    if (!toks || toks.length === 0 || toks[0] === "") return;
    const n = parseInt(toks[0], 10);
    const merged = [];
    for (let i = 1; i <= 2 * n; i++) merged.push(BigInt(toks[i]));
    merged.sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
    const sum = merged[n - 1] + merged[n];
    if (sum % 2n === 0n) console.log((sum / 2n).toString());
    else console.log((Number(sum) / 2).toString());
}
main();

